package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.listener.live.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import com.greenocean.backend.account.service.AccountService;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true","greenocean.listener-support.followup-enabled=true","greenocean.listener-support.extension-enabled=true"}) @ActiveProfiles("test") @Transactional
class PhaseN3RetentionTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerSupportPolicy p;@Autowired LiveSupportService live;@Autowired ListenerSessions sessions;@Autowired ListenerSupportRetention retention;@Autowired AccountService accounts;
 PhaseIFixtures.Actor member,listener,staff;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);live.setAvailability(listener.id(),listener.session(),0,true,null);}
 LiveSupportView active(){var r=live.create(member.id(),UUID.randomUUID(),listener.id());live.accept(r.id(),listener.id());return live.activate(r.id(),member.id());}
 void clock(Instant at){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+at+"'::timestamptz $$");}
 @Test @Tag("happy") void ownerExportIncludesOnlyOwnFeedbackAndDurationMetadata(){var r=active();live.end(r.id(),member.id());sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(true,false,null,0));assertThat(accounts.archive(member.id()).listenerPlanning().get("feedback").toString()).contains(r.id().toString(),"helpful=true");assertThat(accounts.archive(listener.id()).listenerPlanning().get("feedback").toString()).doesNotContain(r.id().toString());}
 @Test @Tag("happy") void thirtyDayDryRunDoesNotDeleteAndApprovedSyntheticPurgeRemovesOnlyNMetadata(){var r=active();UUID e=(UUID)((Map<?,?>)sessions.request(r.id(),member.id(),new ListenerSessions.Proposal(UUID.randomUUID())).get("extension")).get("id");sessions.decide(r.id(),e,listener.id(),true);db.update("INSERT INTO messages(id,conversation_id,sender_id,message_kind,body,client_message_id) VALUES(?,?,?,'USER','Synthetic transcript preserved under existing I policy',?)",UUID.randomUUID(),r.conversationId(),member.id(),UUID.randomUUID());live.end(r.id(),member.id());sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(true,null,null,0));clock(p.now().plus(Duration.ofDays(31)));assertThat(retention.purge()).isEmpty();assertThat(db.queryForObject("SELECT count(*) FROM listener_session_feedback WHERE session_id=?",Integer.class,r.id())).isEqualTo(1);var actual=new ListenerSupportRetention(p,new ListenerDataPolicy(true,true,"synthetic-purge-test","30","30","30","30","30"));var result=actual.purge();assertThat(result.get("FEEDBACK")).isEqualTo(1);assertThat(result.get("EXTENSION")).isEqualTo(1);assertThat(db.queryForObject("SELECT planned_seconds FROM live_support_requests WHERE id=?",Integer.class,r.id())).isNull();assertThat(db.queryForList("SELECT body FROM messages WHERE conversation_id=?",String.class,r.conversationId())).contains("Synthetic transcript preserved under existing I policy");assertThat(actual.purge().values()).allMatch(n->n==0);}
 @Test @Tag("malicious") void unapprovedPolicyCannotEnableProcessingOrRealDeletion(){var missing=new ListenerDataPolicy(false,true,"","30","30","30","30","30");assertThat(missing.approved()).isFalse();assertThat(missing.purgeEnabled()).isFalse();assertThat(new ListenerSupportRetention(p,missing).purge()).isEmpty();assertThatThrownBy(()->new ListenerDataPolicy(true,true,"synthetic","0","30","30","30","30")).isInstanceOf(IllegalArgumentException.class);}
 @Test @Tag("confused") void feedbackWindowClosesAfterThirtyDaysWithoutRenewalThroughEdits(){var r=active();live.end(r.id(),member.id());clock(p.now().plus(Duration.ofDays(31)));assertThat(sessions.plan(r.id(),member.id()).get("feedbackAllowed")).isEqualTo(false);assertThatThrownBy(()->sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(true,null,null,0))).hasMessageContaining("window ended");}
 @Test @Tag("malicious") void eligibleOldMetadataIsPurgedWithoutTouchingANewActiveSession(){var old=active();live.end(old.id(),member.id());sessions.saveFeedback(old.id(),member.id(),new ListenerSessions.Feedback(true,null,null,0));clock(p.now().plus(Duration.ofDays(31)));live.setAvailability(listener.id(),listener.session(),0,true,null);var current=active();var actual=new ListenerSupportRetention(p,new ListenerDataPolicy(true,true,"synthetic-active-preservation","30","30","30","30","30"));actual.purge();assertThat(db.queryForObject("SELECT planned_seconds FROM live_support_requests WHERE id=?",Integer.class,old.id())).isNull();assertThat(live.get(current.id(),member.id()).status()).isEqualTo("ACTIVE");assertThat(live.get(current.id(),member.id()).plannedEndsAt()).isEqualTo(current.plannedEndsAt());}
}
